"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

from dataclasses import dataclass
import calendar
import re
from datetime import datetime

_DIGITS = re.compile(r"[0-9]+")
_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), ([0-9]{2}) "
    r"(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
           "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _get(headers, name):
    for k, v in headers.items():
        if k.lower() == name:
            return v
    return None


def _split_directives(text):
    parts, buf, in_quotes, escaped = [], [], False, False
    for ch in text:
        if in_quotes:
            buf.append(ch)
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_quotes = False
        elif ch == '"':
            in_quotes = True
            buf.append(ch)
        elif ch == ",":
            parts.append("".join(buf))
            buf = []
        else:
            buf.append(ch)
    parts.append("".join(buf))
    return parts


def _parse_cache_control(headers):
    """Return {name: value-or-None}; last occurrence wins."""
    out = {}
    text = _get(headers, "cache-control")
    if text is None:
        return out
    for part in _split_directives(text):
        part = part.strip()
        if not part:
            continue
        if "=" in part:
            name, value = part.split("=", 1)
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
        else:
            name, value = part, None
        name = name.strip().lower()
        if not name:
            continue
        out[name] = value
    return out


def _num(directives, name):
    value = directives.get(name)
    if value is not None and _DIGITS.fullmatch(value):
        return int(value)
    return None


def _parse_date(headers, name):
    raw = _get(headers, name)
    if raw is None:
        return None
    m = _DATE.fullmatch(raw.strip())
    if not m:
        raise HeaderError(f"malformed {name} header: {raw!r}")
    _, day, mon, year, hh, mm, ss = m.groups()
    try:
        dt = datetime(int(year), _MONTHS.index(mon) + 1, int(day),
                      int(hh), int(mm), int(ss))
    except ValueError as exc:
        raise HeaderError(f"invalid {name} header: {raw!r}") from exc
    return calendar.timegm(dt.timetuple())


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    res_cc = _parse_cache_control(response_headers)
    req_cc = _parse_cache_control(request_headers)

    date = _parse_date(response_headers, "date")
    expires = _parse_date(response_headers, "expires")
    last_modified = _parse_date(response_headers, "last-modified")
    if date is None:
        date = response_time

    age_raw = _get(response_headers, "age")
    age = 0
    if age_raw is not None and _DIGITS.fullmatch(age_raw.strip()):
        age = int(age_raw.strip())

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = age + response_delay
    initial_age = max(apparent_age, corrected_age)
    current_age = initial_age + (now - response_time)

    s_maxage = _num(res_cc, "s-maxage")
    max_age = _num(res_cc, "max-age")
    if s_maxage is not None:
        lifetime = s_maxage
    elif max_age is not None:
        lifetime = max_age
    elif expires is not None:
        lifetime = expires - date
    elif last_modified is not None:
        lifetime = (date - last_modified) // 10
    else:
        lifetime = 0
    lifetime = max(0, lifetime)

    req_max_age = _num(req_cc, "max-age")
    if req_max_age is not None:
        lifetime = min(lifetime, req_max_age)

    if (any(d in res_cc for d in ("no-store", "no-cache", "must-revalidate"))
            or "no-cache" in req_cc):
        return Result(MUST_REVALIDATE, current_age, lifetime)

    min_fresh = _num(req_cc, "min-fresh") or 0
    if lifetime > current_age + min_fresh:
        return Result(FRESH, current_age, lifetime)

    if "max-stale" in req_cc:
        value = req_cc["max-stale"]
        if value is None:
            return Result(FRESH, current_age, lifetime)
        if _DIGITS.fullmatch(value) and current_age - lifetime <= int(value):
            return Result(FRESH, current_age, lifetime)

    return Result(STALE, current_age, lifetime)
